const PRODUCTS = CATALOG.products;
/** Network services products compose (declared under `defxn.resolvers`). */
const RESOLVERS = CATALOG.resolvers ?? [];

function productById(id) {
  return PRODUCTS.find((product) => product.id === id) ?? null;
}

function laneById(id) {
  return LANES.find((lane) => lane.id === id) ?? null;
}

const SVG_NS = 'http://www.w3.org/2000/svg';

/** The product's glyph (from DEFXN's one icon set) as an inline SVG element.
    Decorative: aria-hidden, because a label always sits beside it. */
function productIcon(id, { size = 18, className = 'dx-glyph' } = {}) {
  const product = productById(id) ?? RESOLVERS.find((resolver) => resolver.id === id);
  return glyph(product?.icon, { size, className });
}

